package org.dromara.sports.tables.d10.growth_policy;
import com.fasterxml.jackson.databind.*;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.api.GrowthPolicyApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;
@Service @RequiredArgsConstructor
public class GrowthPolicies implements GrowthPolicyApi,CapabilityProvider {
    private final ScopedJdbc db; private final ObjectMapper json;
    public List<CapabilityDefinition> capabilities(){return List.of(capability(json,"growth.policy.save","发布下一版成长规则，仅影响新赛事事实","asp_growth_policy",false,true,Set.of("admin"),"sports:platform:manage",Set.of("asp_growth_policy","asp_sport","asp_event"),Set.of("asp_growth_policy"),"sportId","rulesJson","expectedVersion"));}
    public JsonNode preview(String code,JsonNode in){return safeJson(json,db.list("SELECT revision,rules::text AS rules,status,create_time FROM asp_growth_policy WHERE sport_id=? AND code='participation' ORDER BY revision DESC",id(in,"sportId")));}
    public JsonNode execute(String code,JsonNode in){long sport=id(in,"sportId");db.lock("growth-policy:"+sport);var latest=db.one("SELECT revision FROM asp_growth_policy WHERE sport_id=? AND code='participation' ORDER BY revision DESC LIMIT 1",sport);int old=latest==null?0:(int)number(latest.get("revision"));if(old!=in.path("expectedVersion").asInt(-1))throw fail("规则版本已变化，请重新读取",409);if(db.count("SELECT count(*) FROM asp_sport WHERE id=?",sport)==0)throw fail("运动不存在",404);JsonNode rules=parse(text(in,"rulesJson",10000));read(old+1,rules);db.update("UPDATE asp_growth_policy SET status='superseded',version=version+1,update_time=CURRENT_TIMESTAMP WHERE sport_id=? AND code='participation' AND status='active'",sport);long id=nextId();db.update("INSERT INTO asp_growth_policy(id,sport_id,code,revision,rules,status) VALUES (?,?,'participation',?,?::jsonb,'active')",id,sport,old+1,rules.toString());return reference(json,"policyId",id,"active");}
    public Rule current(Long sport){return select(sport,null);}
    public Rule forEvent(Long sport,Long event){return select(sport,event);}
    private Rule select(long sport,Long event){var row=event==null?db.one("SELECT revision,rules::text AS rules FROM asp_growth_policy WHERE sport_id=? AND code='participation' AND status='active' ORDER BY revision DESC LIMIT 1",sport):db.one("SELECT p.revision,p.rules::text AS rules FROM asp_growth_policy p JOIN asp_event e ON e.id=? WHERE p.sport_id=? AND p.code='participation' AND p.status IN('active','superseded') AND (p.create_time<=e.create_time OR p.revision=(SELECT min(p0.revision) FROM asp_growth_policy p0 WHERE p0.sport_id=p.sport_id AND p0.code=p.code)) ORDER BY p.revision DESC LIMIT 1",event,sport);if(row==null)throw fail("该运动成长规则尚未发布",409);return read((int)number(row.get("revision")),parse(row.get("rules").toString()));}
    private JsonNode parse(String source){try{return json.readTree(source);}catch(Exception e){throw fail("成长规则格式无法读取",400);}}
    private Rule read(int version,JsonNode rules){var thresholds=new ArrayList<Long>();var names=new ArrayList<String>();for(var value:rules.path("thresholds")){if(!value.isIntegralNumber()||value.asLong()<0||value.asLong()>10000000)throw fail("段位门槛须为合理非负整数",400);thresholds.add(value.asLong());}for(var value:rules.path("rankNames")){String name=value.asText();if(name.isBlank()||name.length()>20)throw fail("请填写有效段位名称",400);names.add(name);}if((thresholds.size()!=7&&thresholds.size()!=8&&thresholds.size()!=9)||names.size()!=thresholds.size()||thresholds.get(0)!=0)throw fail("请配置从0分开始的七、八或九个等级，保留历史规则",400);for(int i=1;i<thresholds.size();i++)if(thresholds.get(i)<=thresholds.get(i-1))throw fail("段位门槛须依次递增",400);var personal=counts(rules,"personalTitles",Set.of("first_checkin","first_finish","regular"));var team=counts(rules,"teamTitles",Set.of("team_first","team_partners","team_veterans"));return new Rule("participation-v"+version,points(rules,"checkinPoints"),points(rules,"finishPoints"),points(rules,"teamFinishPoints"),List.copyOf(thresholds),List.copyOf(names),personal,team);}
    private int points(JsonNode n,String key){if(!n.path(key).isInt()||n.path(key).asInt()<0||n.path(key).asInt()>10000)throw fail("奖励积分须为0至10000的整数",400);return n.path(key).asInt();}
    private Map<String,Integer> counts(JsonNode n,String key,Set<String> codes){var map=new HashMap<String,Integer>();for(String code:codes){var value=n.path(key).path(code);if(!value.isInt()||value.asInt()<1||value.asInt()>10000)throw fail("称号次数须为1至10000的整数",400);map.put(code,value.asInt());}return Map.copyOf(map);}
}
